import unittest
from candidate import sort_numbers

class TestSortNumbers(unittest.TestCase):
    def test_sort_numbers_normal_case(self):
        self.assertEqual(sort_numbers('three one five'), 'one three five')

    def test_sort_numbers_empty_string(self):
        self.assertEqual(sort_numbers(''), '')

    def test_sort_numbers_only_spaces(self):
        self.assertEqual(sort_numbers('   '), '')

    def test_sort_numbers_leading_trailing_spaces(self):
        self.assertEqual(sort_numbers('  three one   five  '), 'one three five')

    def test_sort_numbers_multiple_spaces_between_tokens(self):
        self.assertEqual(sort_numbers('three   one    five'), 'one three five')

    def test_sort_numbers_duplicate_numbers(self):
        self.assertEqual(sort_numbers('two two one'), 'one two two')

    def test_sort_numbers_stable_sort_for_duplicates(self):
        self.assertEqual(sort_numbers('one one two two one'), 'one one one two two')

    def test_sort_numbers_all_digits(self):
        expected = 'zero one two three four five six seven eight nine'
        input_str = 'seven five three nine one six two four zero eight'
        self.assertEqual(sort_numbers(input_str), expected)

    def test_sort_numbers_invalid_token(self):
        with self.assertRaises(KeyError):
            sort_numbers('ten one two')

    def test_sort_numbers_case_sensitive(self):
        with self.assertRaises(KeyError):
            sort_numbers('One two three')

    def test_sort_numbers_none_input(self):
        with self.assertRaises(AttributeError):
            sort_numbers(None)

    def test_sort_numbers_non_string_input(self):
        with self.assertRaises(AttributeError):
            sort_numbers(123)

    def test_sort_numbers_output_type(self):
        result = sort_numbers('three one')
        self.assertIsInstance(result, str)

    def test_sort_numbers_sorted_order(self):
        self.assertEqual(sort_numbers('nine eight seven six five four three two one zero'), 'zero one two three four five six seven eight nine')

if __name__ == '__main__':
    unittest.main()
